import {mapGetters} from "vuex";
import {getDictList} from "@/api/dict";
import {updateDeviceEvalute} from "@/api/device/oldEquipmentLibrary.js";

export default {
  props: {
  },
  data() {
    return {
      isShow: true,
      searchForm: {
        current: 1,
        size: 20,
        deviceStatus:'',
        deviceType:'',
      },
      // 表格
      tableData: [

      ],
      tableHeight: '550px',
      loading: false,
      total: 0,
      selectList: [],
      list: [],
      active:1,
      isEdit:false,
      isOrNotList:[],
      scale:1,
    };
  },
  computed: {
    ...mapGetters(["userInfo", "userDetail"]),
  },
 async  mounted(){

    this.setTableHeight();
  await  this.getDictList("needNo");
       this.tableData = this.$route.query.data;
      this.scale = document

  },
  methods: {
     select(val) {
      this.selectList = val;
    },
     async getDictList(code) {
      await   getDictList(code).then(res => {
            if(code === 'needNo'){
             this.isOrNotList = res.data;
          }
        });
      },

      handleCancel(){
        this.$closePage("/assets/oldEquipmentLibrary");
     },

    handleSave() {
      if (this.tableData.length == 0) {
        this.$message.warning("当前暂无数据!")
        return
      }

      let list = [];
      if(this.selectList.length === 0){
          list = [...this.tableData];
      }else{
        list = [...this.selectList];
      }

      let canSave = true;
      list.map((item,index)=> {
         if(!item.isChange){
          let tip = '第' + (index + 1)+ '条数据自评是否更换不能为空'
           this.$message.warning(tip)
           canSave = false;
           return
         }
          if(!item.changeReason){
          let tip = '第' + (index + 1)+ '条数据自评更换原因不能为空'
           this.$message.warning(tip)
           canSave = false;
           return
         }
      })

      if(canSave == true){
              updateDeviceEvalute(list).then((res) => {
        if (res.code != 200) {
          throw res.msg;
        }
        this.$message({
          message: "字段修改成功",
          type: "success",
        });

         this.$closePage("/assets/oldEquipmentLibrary");
       });
      }
    },

    // 设置表格高度
    setTableHeight() {
      let pageBody = document.getElementsByClassName('page_body')
      // console.log(pageBody[0].offsetHeight);
      this.tableHeight = pageBody[0].offsetHeight + 'px'
    },
  }
};
